	protected Authorization read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Authorization" );

		Authorization entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Authorization with primary key" );
		msg.append( authorizationId );
		
		AuthorizationFetchOneSummary fetchOneSummary = new AuthorizationFetchOneSummary( authorizationId );

		try {
			entity = AuthorizationService.getAuthorizationInstance().getAuthorization( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Authorization " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Authorization.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Authorization." );

		StringBuilder msg = new StringBuilder( "Failed to update a Authorization : " );        
		Authorization entity = read();
		UpdateAuthorizationCommand command = generateUpdateCommand();
		command.setAuthorizationId(entity.getAuthorizationId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Authorization." );

			// for use later on...
			authorizationId = entity.getAuthorizationId();

			AuthorizationService proxy = AuthorizationService.getAuthorizationInstance();  

			proxy.updateAuthorization( command ).get();

			LOGGER.info( "-- Successfully saved Authorization - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + authorizationId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Authorization.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Authorization." );

		Authorization entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Authorization with id " + authorizationId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Authorization with id " + authorizationId );

			throw e;
		}

		try{
			AuthorizationService.getAuthorizationInstance().delete( new DeleteAuthorizationCommand( entity.getAuthorizationId() ) ).get();
			LOGGER.info( "-- Successfully deleted Authorization with id " + authorizationId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Authorization with id " + authorizationId );

			throw e;
		}
	}

	/**
	 * get all Authorizations.
	 */
	protected List<Authorization> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Authorizations:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Authorization : " );        
		List<Authorization> collection  = new ArrayList<>();

		try {
			// call the static get method on the AuthorizationService
			collection = AuthorizationService.getAuthorizationInstance().getAllAuthorization();
			assertNotNull( collection, "An Empty collection of Authorization was incorrectly returned.");
			
			// Now print out the values
			Authorization entity = null;            
			Iterator<Authorization> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getAuthorizationId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

